using VisualStudioLikeIDE.Compiler;
using VisualStudioLikeIDE.Compiler.Diagnostics;
using VisualStudioLikeIDE.Compiler.Emit;
using VisualStudioLikeIDE.Compiler.Nodes;

namespace VisualStudioLikeIDE.Tests;

public sealed class CodeGenerationTests
{
    private const string Header = """
        // <auto-generated>
        //     Generated by VisualStudioLikeIDE from Graphs/Program.graph.json.
        //     Changes to this file are overwritten when the graph is compiled.
        // </auto-generated>

        #nullable enable


        """;

    private static readonly GraphCompiler Compiler = new(NodeLibrary.CreateDefault());

    internal static GraphCompilationResult Compile(GraphBuilder builder) =>
        Compiler.Compile(builder.Graph, new GraphCompilationOptions("Demo"), "Graphs/Program.graph.json");

    private static string Generate(GraphBuilder builder)
    {
        GraphCompilationResult result = Compile(builder);
        Assert.True(result.Success, string.Join("\n", result.Diagnostics));
        GeneratedSource source = result.Source!;

        // Every generated file must also be valid C# according to Roslyn.
        IReadOnlyList<GraphDiagnostic> roslyn = RoslynVerifier.Verify("Demo", [new VerificationSource("Program.g.cs", source.Text, source)], isExecutable: true);
        Assert.Empty(roslyn);
        return source.Text;
    }

    private static string Expected(string body) => (Header + body + "\n").ReplaceLineEndings("\n");

    [Fact]
    public void HelloWorldGeneratesPlainConsoleProgram()
    {
        var graph = new GraphBuilder();
        string entry = graph.Node(BuiltInNodes.EntryTypeId);
        graph.Then(entry, graph.PrintLiteral("Hello, World!"));

        Assert.Equal(Expected("""
            using System;

            namespace Demo;

            internal static class Program
            {
                public static void Main()
                {
                    Console.WriteLine("Hello, World!");
                }
            }
            """), Generate(graph));
    }

    [Fact]
    public void CommentsDoNotChangeGeneratedCode()
    {
        var graph = new GraphBuilder();
        string entry = graph.Node(BuiltInNodes.EntryTypeId);
        graph.Then(entry, graph.PrintLiteral("Hello, World!"));
        string without = Generate(graph);

        graph.Graph.Comments.Add(new GraphModel.GraphComment { Id = "note", X = -20, Y = -40, Width = 400, Height = 200, Text = "Greeting" });

        Assert.Equal(without, Generate(graph));
    }

    [Fact]
    public void BranchThatRejoinsGeneratesIfElseFollowedByContinuation()
    {
        var graph = new GraphBuilder();
        string entry = graph.Node(BuiltInNodes.EntryTypeId);
        string read = graph.Node("console.read-line");
        string parse = graph.Node("convert.string-to-int");
        string branch = graph.Node("core.branch");
        string condition = graph.Node("compare.int.less-or-equal");
        string zero = graph.Node("literal.int", "0");
        string dead = graph.PrintLiteral("Dead");
        string alive = graph.PrintLiteral("Alive");
        string done = graph.PrintLiteral("Done");
        graph.Then(entry, read)
            .Then(read, branch)
            .Connect(read, "line", parse, "text")
            .Connect(parse, "value", condition, "a")
            .Connect(zero, "value", condition, "b")
            .Connect(condition, "result", branch, "condition")
            .Then(branch, dead, "true")
            .Then(branch, alive, "false")
            .Then(dead, done)
            .Then(alive, done);

        Assert.Equal(Expected("""
            using System;

            namespace Demo;

            internal static class Program
            {
                public static void Main()
                {
                    string line = Console.ReadLine() ?? "";
                    if (int.Parse(line) <= 0)
                    {
                        Console.WriteLine("Dead");
                    }
                    else
                    {
                        Console.WriteLine("Alive");
                    }

                    Console.WriteLine("Done");
                }
            }
            """), Generate(graph));
    }

    [Fact]
    public void ReturnInBranchArmRemovesRedundantElse()
    {
        var graph = new GraphBuilder();
        string entry = graph.Node(BuiltInNodes.EntryTypeId);
        string read = graph.Node("console.read-line");
        string branch = graph.Node("core.branch");
        string isEmpty = graph.Node("string.equals");
        string empty = graph.Node("literal.string", "");
        string message = graph.PrintLiteral("Nothing entered.");
        string stop = graph.Node("core.return");
        string echo = graph.Node("console.write-line");
        graph.Then(entry, read)
            .Then(read, branch)
            .Connect(read, "line", isEmpty, "a")
            .Connect(empty, "value", isEmpty, "b")
            .Connect(isEmpty, "result", branch, "condition")
            .Then(branch, message, "true")
            .Then(message, stop)
            .Then(branch, echo, "false")
            .Connect(read, "line", echo, "text");

        Assert.Equal(Expected("""
            using System;

            namespace Demo;

            internal static class Program
            {
                public static void Main()
                {
                    string line = Console.ReadLine() ?? "";
                    if (line == "")
                    {
                        Console.WriteLine("Nothing entered.");
                        return;
                    }

                    Console.WriteLine(line);
                }
            }
            """), Generate(graph));
    }

    [Fact]
    public void EmptyTrueArmInvertsCondition()
    {
        var graph = new GraphBuilder();
        string entry = graph.Node(BuiltInNodes.EntryTypeId);
        string read = graph.Node("console.read-line");
        string branch = graph.Node("core.branch");
        string isEmpty = graph.Node("string.equals");
        string empty = graph.Node("literal.string", "");
        string not = graph.Node("logic.not");
        string print = graph.PrintLiteral("Empty");
        graph.Then(entry, read)
            .Then(read, branch)
            .Connect(read, "line", isEmpty, "a")
            .Connect(empty, "value", isEmpty, "b")
            .Connect(isEmpty, "result", not, "value")
            .Connect(not, "result", branch, "condition")
            .Then(branch, print, "false");

        Assert.Contains("if (line == \"\")\n        {\n            Console.WriteLine(\"Empty\");", Generate(graph), StringComparison.Ordinal);
    }

    [Fact]
    public void OperatorPrecedenceIsPreservedWithMinimalParentheses()
    {
        // (1 + 2) * (3 - (4 - 5)), printed through ToString.
        var graph = new GraphBuilder();
        string entry = graph.Node(BuiltInNodes.EntryTypeId);
        string print = graph.Node("console.write-line");
        string toText = graph.Node("convert.int-to-string");
        string multiply = graph.Node("math.int.multiply");
        string add = graph.Node("math.int.add");
        string outer = graph.Node("math.int.subtract");
        string inner = graph.Node("math.int.subtract");
        string[] literals = [.. Enumerable.Range(1, 5).Select(value => graph.Node("literal.int", value.ToString(System.Globalization.CultureInfo.InvariantCulture)))];
        graph.Then(entry, print)
            .Connect(toText, "text", print, "text")
            .Connect(multiply, "result", toText, "value")
            .Connect(add, "result", multiply, "a")
            .Connect(outer, "result", multiply, "b")
            .Connect(literals[0], "value", add, "a")
            .Connect(literals[1], "value", add, "b")
            .Connect(literals[2], "value", outer, "a")
            .Connect(inner, "result", outer, "b")
            .Connect(literals[3], "value", inner, "a")
            .Connect(literals[4], "value", inner, "b");

        Assert.Contains("Console.WriteLine(((1 + 2) * (3 - (4 - 5))).ToString());", Generate(graph), StringComparison.Ordinal);
    }

    [Theory]
    [InlineData("literal.int", "-5", "convert.int-to-string", "(-5).ToString()")]
    [InlineData("literal.int", "-2147483648", "convert.int-to-string", "(-2147483648).ToString()")]
    [InlineData("literal.double", "2", "convert.double-to-string", "2.0.ToString()")]
    [InlineData("literal.double", "0.1", "convert.double-to-string", "0.1.ToString()")]
    [InlineData("literal.bool", "false", "convert.bool-to-string", "false.ToString()")]
    public void LiteralsRoundTripExactly(string literalType, string value, string conversion, string expected)
    {
        var graph = new GraphBuilder();
        string entry = graph.Node(BuiltInNodes.EntryTypeId);
        string print = graph.Node("console.write-line");
        string convert = graph.Node(conversion);
        string literal = graph.Node(literalType, value);
        graph.Then(entry, print)
            .Connect(convert, "text", print, "text")
            .Connect(literal, "value", convert, "value");

        Assert.Contains($"Console.WriteLine({expected});", Generate(graph), StringComparison.Ordinal);
    }

    [Fact]
    public void StringLiteralsAreEscaped()
    {
        var graph = new GraphBuilder();
        string entry = graph.Node(BuiltInNodes.EntryTypeId);
        graph.Then(entry, graph.PrintLiteral("Quote \" backslash \\ newline \n tab \t"));

        Assert.Contains("""Console.WriteLine("Quote \" backslash \\ newline \n tab \t");""", Generate(graph), StringComparison.Ordinal);
    }

    [Fact]
    public void IntegerFeedingNumberInputIsConvertedExplicitly()
    {
        var graph = new GraphBuilder();
        string entry = graph.Node(BuiltInNodes.EntryTypeId);
        string print = graph.Node("console.write-line");
        string toText = graph.Node("convert.double-to-string");
        string add = graph.Node("math.double.add");
        string parse = graph.Node("convert.string-to-int");
        string text = graph.Node("literal.string", "41");
        string one = graph.Node("literal.int", "1");
        graph.Then(entry, print)
            .Connect(toText, "text", print, "text")
            .Connect(add, "result", toText, "value")
            .Connect(parse, "value", add, "a")
            .Connect(text, "value", parse, "text")
            .Connect(one, "value", add, "b");

        // int.Parse(...) + 1 alone would be integer addition; the conversion keeps the Number semantics of the node.
        Assert.Contains("Console.WriteLine(((double)int.Parse(\"41\") + 1.0).ToString());", Generate(graph), StringComparison.Ordinal);
    }

    [Fact]
    public void UnusedReadLineOutputDoesNotDeclareLocal()
    {
        var graph = new GraphBuilder();
        string entry = graph.Node(BuiltInNodes.EntryTypeId);
        string read = graph.Node("console.read-line");
        graph.Then(entry, read);

        Assert.Contains("        Console.ReadLine();\n", Generate(graph), StringComparison.Ordinal);
    }

    [Fact]
    public void LocalNamesAreUnique()
    {
        var graph = new GraphBuilder();
        string entry = graph.Node(BuiltInNodes.EntryTypeId);
        string first = graph.Node("console.read-line");
        string second = graph.Node("console.read-line");
        string concat = graph.Node("string.concat");
        string print = graph.Node("console.write-line");
        graph.Then(entry, first).Then(first, second).Then(second, print)
            .Connect(first, "line", concat, "a")
            .Connect(second, "line", concat, "b")
            .Connect(concat, "result", print, "text");

        string code = Generate(graph);
        Assert.Contains("string line = Console.ReadLine() ?? \"\";", code, StringComparison.Ordinal);
        Assert.Contains("string line2 = Console.ReadLine() ?? \"\";", code, StringComparison.Ordinal);
        Assert.Contains("Console.WriteLine(line + line2);", code, StringComparison.Ordinal);
    }

    [Fact]
    public void GenerationIsDeterministicAndIndependentOfNodeOrder()
    {
        var graph = new GraphBuilder();
        string entry = graph.Node(BuiltInNodes.EntryTypeId);
        graph.Then(entry, graph.PrintLiteral("A"));
        string first = Generate(graph);

        graph.Graph.Nodes.Reverse();
        graph.Graph.Connections.Reverse();
        Assert.Equal(first, Generate(graph));
    }

    [Fact]
    public void SourceMapPointsAtGeneratedStatements()
    {
        var graph = new GraphBuilder();
        string entry = graph.Node(BuiltInNodes.EntryTypeId);
        string print = graph.PrintLiteral("Hello");
        graph.Then(entry, print);

        GeneratedSource source = Compile(graph).Source!;
        SourceMapEntry entryForPrint = Assert.Single(source.SourceMap);
        Assert.Equal(print, entryForPrint.NodeId);
        string line = source.Text.Split('\n')[entryForPrint.StartLine - 1];
        Assert.Equal("        Console.WriteLine(\"Hello\");", line);
        Assert.Equal(print, source.FindLine(entryForPrint.StartLine)?.NodeId);
    }

    [Fact]
    public void LongChainsCompileWithoutStackOverflow()
    {
        var graph = new GraphBuilder();
        string previous = graph.Node(BuiltInNodes.EntryTypeId);
        for (int i = 0; i < 5_000; i++)
        {
            string print = graph.PrintLiteral("Line");
            graph.Then(previous, print);
            previous = print;
        }

        GraphCompilationResult result = Compile(graph);
        Assert.True(result.Success);
        Assert.Equal(5_000, result.Source!.SourceMap.Count);
    }
}
